import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
// Dacă vei folosi Firebase
import { db, storage } from "../../firebase"; // configurează tu Firebase
import { collection, addDoc } from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";

const AddPetPage = () => {
    const navigate = useNavigate();
    const [petData, setPetData] = useState({
        name: "",
        breed: "",
        age: "",
        description: "",
        type: "",
        imageFile: null,
    });

    const handleChange = (e) => {
        const { name, value, files } = e.target;
        if (files) {
            setPetData({ ...petData, imageFile: files[0] });
        } else {
            setPetData({ ...petData, [name]: value });
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            let imageUrl = "";
            if (petData.imageFile) {
                const storageRef = ref(storage, `pets/${petData.imageFile.name}`);
                await uploadBytes(storageRef, petData.imageFile);
                imageUrl = await getDownloadURL(storageRef);
            }

            await addDoc(collection(db, "pets"), {
                name: petData.name,
                breed: petData.breed,
                age: petData.age,
                type: petData.type,
                description: petData.description,
                image: imageUrl,
                shelterId: "SHELTER_ID_HERE", // pune aici user.uid
                adoptionStatus: "available",
                createdAt: new Date(),
            });

            alert("Pet added successfully!");
            navigate("/shelter"); // revine la dashboard
        } catch (err) {
            console.error(err);
            alert("Error adding pet");
        }
    };

    return (
        <div style={{ padding: "20px" }}>
            <h2>Add a New Pet 🐶🐱</h2>
            <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", maxWidth: "400px" }}>
                <input type="text" name="name" placeholder="Pet Name" onChange={handleChange} required />
                <input type="text" name="breed" placeholder="Breed" onChange={handleChange} required />
                <input type="text" name="age" placeholder="Age" onChange={handleChange} required />
                <select name="type" onChange={handleChange} required>
                    <option value="">Select Type</option>
                    <option value="dog">Dog</option>
                    <option value="cat">Cat</option>
                    <option value="other">Other</option>
                </select>
                <textarea name="description" placeholder="Description" onChange={handleChange} />
                <input type="file" name="imageFile" onChange={handleChange} />
                <button type="submit" style={{ marginTop: "10px", padding: "10px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "5px" }}>Add Pet</button>
            </form>
        </div>
    );
};

export default AddPetPage;
